Here is a clean Template Method implementation for sorting in Python:

```python
from abc import ABC, abstractmethod
from typing import List, Any

class SortAlgorithm(ABC):
    def __init__(self, data: List[Any]):
        self.data = data

    def sort(self) -> List[Any]:
        """Template method - defines the sorting skeleton."""
        self.do_sort()
        return self.data

    @abstractmethod
    def do_sort(self):
        """Concrete algorithm steps implemented by subclasses."""
        pass

    def compare(self, a: Any, b: Any) -> bool:
        """Hook to compare two elements. Can be overridden for custom ordering."""
        return a > b

    def swap(self, i: int, j: int):
        """Hook to swap two elements."""
        self.data[i], self.data[j] = self.data[j], self.data[i]


class BubbleSort(SortAlgorithm):
    def do_sort(self):
        n = len(self.data)
        for i in range(n):
            swapped = False
            for j in range(0, n - i - 1):
                if self.compare(self.data[j], self.data[j + 1]):
                    self.swap(j, j + 1)
                    swapped = True
            if not swapped:
                break


class SelectionSort(SortAlgorithm):
    def do_sort(self):
        n = len(self.data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(self.data[min_idx], self.data[j]):
                    min_idx = j
            if min_idx != i:
                self.swap(i, min_idx)


# Test
if __name__ == "__main__":
    ints = [5, 2, 9, 1, 5, 6]
    strs = ["banana", "apple", "cherry", "date"]

    print("BubbleSort ints:", BubbleSort(ints.copy()).sort())
    print("SelectionSort ints:", SelectionSort(ints.copy()).sort())

    print("BubbleSort strs:", BubbleSort(strs.copy()).sort())
    print("SelectionSort strs:", SelectionSort(strs.copy()).sort())
```

`SortAlgorithm.sort` is the template method. The concrete subclasses `BubbleSort` and `SelectionSort` provide their own `do_sort` implementation while reusing the `compare` and `swap` hooks defined in the base class.
